import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def bgc2(g): return Counter(x for row in g for x in row).most_common(1)[0][0]
def comps_m(g,bg):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i2 in range(h):
        for j2 in range(w):
            if g[i2][j2]!=bg and not seen[i2][j2]:
                st=[(i2,j2,g[i2][j2])]; seen[i2][j2]=True; cc2=[]
                while st:
                    a_,bb,col=st.pop(); cc2.append((a_,bb,col))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            x,y=a_+dx,bb+dy
                            if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]!=bg:
                                seen[x][y]=True; st.append((x,y,g[x][y]))
                out.append(cc2)
    return out
def norm(t):
    rs=[p[0] for p in t]; cs=[p[1] for p in t]
    return [(r-min(rs),c-min(cs),v) for r,c,v in t]
